def current_review_policy(connection: sqlite3.Connection, record: AssessmentRecord) -> CurrentReviewPolicy:
    policy = Policy(connection, record.workspace_id)
    policy.check("attempt_read", attempt_id=record.id)
    policy.check("subject_read")
    scope: Literal["operation_help_only", "academic"] = "academic"
    for ref in record.question_refs:
        try:
            policy.check("practice_hint", question_ref=ref)
        except ApiError as error:
            if error.code != "ASSESSMENT_ANSWER_PROTECTED":
                raise
            scope = "operation_help_only"
    return CurrentReviewPolicy(tutor_scope=scope, allow_materials=True, allow_web=False)


class GradingService:
    def __init__(self, database: Database):
        self.database = database

    def result(self, identity: SessionIdentity, identifier: str) -> AssessmentGradingResult | AssessmentGradingJob:
        from .evidence import checked_submission_basis, history
        # Complete the immutable projection in a consistent WAL read snapshot,
        # without reserving the writer needed to finish the grading job.
        with self.database.transaction(immediate=False) as connection:
            Policy(connection, identity.workspace_id).check("attempt_read", attempt_id=identifier)
            repo = GradingRepository(connection, identity.workspace_id)
            record = repo.attempts.load(identifier)
            checked_submission(connection, record)
            checked_submission_basis(connection, identity.workspace_id, identifier)
            entries = history(connection, identity.workspace_id, identifier)
            job = repo.latest_job(identifier)
            if job is None:
                raise ApiError(503, "GRADING_RECOVERY_PENDING", "评分任务正在从持久提交恢复，请稍后重试。", True)
            grade = repo.load_grade(record)
            if job["status"] != "completed":
                previous = self._project(connection, repo, record, grade, entries, release=False) if grade is not None else None
                value: AssessmentGradingResult | AssessmentGradingJob = AssessmentGradingJob(id=job["id"], status=job["status"], last_completed_result=previous, history=entries,
                    current_review_policy=current_review_policy(connection, record))
            else:
                if grade is None:
                    raise invalid_snapshot()
                value = self._project(connection, repo, record, grade, entries, release=record.policy.mode != "independent" or grade[0].status == "graded")
        # Mutable delivery permission must be current, rather than inherited
        # from the old snapshot. Keep this writer reservation to policy checks;
        # history, evidence and material projection have already completed.
        with self.database.transaction() as connection:
            policy = Policy(connection, identity.workspace_id)
            policy.check("attempt_read", attempt_id=identifier)
            current = AssessmentRepository(connection, identity.workspace_id).load(identifier)
            review_policy = current_review_policy(connection, current)
            prepared = value if isinstance(value, AssessmentGradingResult) else value.last_completed_result
            if prepared is not None:
                for item in prepared.items:
                    if item.solution_markdown is not None:
                        policy.check("solution_read", question_ref=item.question_ref)
        if isinstance(value, AssessmentGradingJob) and value.last_completed_result is not None:
            value = value.model_copy(update={"last_completed_result": value.last_completed_result.model_copy(update={"current_review_policy": review_policy})})
        return value.model_copy(update={"current_review_policy": review_policy})

    @staticmethod
    def _project(connection: sqlite3.Connection, repo: GradingRepository, record: AssessmentRecord,
                 grade: tuple[dm.GradingResult, GradeAudit], entries: list[GradeHistoryEntry], *, release: bool) -> AssessmentGradingResult:
        value, audit = grade
        content = AssessmentContent(connection, record.workspace_id)
        reviews = [repo.review(review_id, record)[1] for review_id in audit.review_ids]
        items = []
        solution_reviews = []
        for item, pin in zip(value.items, record.assignment.private_pins, strict=True):
            if release:
                Policy(connection, record.workspace_id).check("solution_read", question_ref=item.question_ref)
                solution = content.solution(pin)
                items.append(item.model_copy(update={"solution_markdown": solution.solution_markdown}))
                solution_reviews.append(ReleasedSolutionReview(question_id=item.question_ref.id, review_status=pin.review_status))
            else:
                items.append(item)
        return AssessmentGradingResult(**value.model_dump(exclude={"items"}), items=items, manual_reviews=reviews,
            solution_reviews=solution_reviews, eligibility_status="evaluated", history=entries,
            current_review_policy=current_review_policy(connection, record),
            review_materials=[QuestionReviewMaterials(question_ref=ref, materials=review_materials(connection, record.workspace_id, ref,
                record.assignment.preflight.course_refs)) for ref in record.question_refs])

Action = Literal['subject_read', 'attempt_read', 'attempt_write', 'practice_hint', 'solution_read', 'private_artifact']


def active_error() -> ApiError:
    return ApiError(409, 'ASSESSMENT_ACTIVE', '独立测试进行中，此操作暂不可用。')


def protected_error() -> ApiError:
    return ApiError(409, 'ASSESSMENT_ANSWER_PROTECTED', '相关测验的帮助或解答仍受策略保护；提交及必要评分完成前暂不可读取。')


class Policy:
    def __init__(self, connection: sqlite3.Connection, workspace_id: str):
        self.connection = connection
        self.workspace_id = workspace_id
        self.assessments = AssessmentAccess(connection, workspace_id)

    def check(self, action: Action, attempt_id: str | None = None, question_ref: dm.ContentRef | None = None) -> None:
        active = self.assessments.active_independent()
        if active is not None:
            if action not in {'attempt_read', 'attempt_write'} or active != attempt_id:
                raise active_error()
        if action in {'attempt_read', 'attempt_write'}:
            if attempt_id is None:
                raise ApiError(422, 'ATTEMPT_REFERENCE_REQUIRED', '此操作需要明确的测验作答。')
            self.assessments.load(attempt_id)
            return
        if action == 'subject_read':
            return
        if action not in {'practice_hint', 'solution_read', 'private_artifact'}:
            raise ApiError(403, 'POLICY_DENIED', '未声明的操作不能越过测验策略。')
        candidates = self.assessments.protected()
        if action == 'practice_hint':
            candidates = tuple(item for item in candidates if item.policy.mode != 'assisted')
        if not candidates:
            return
        # An opaque private original cannot establish that its hidden bytes do
        # not disclose a protected answer. Its safe public derivative stays readable.
        if action == 'private_artifact' or question_ref is None:
            raise protected_error()
        group = question_exposure_group(self.connection, self.workspace_id, question_ref)
        for item in candidates:
            for assigned in item.question_refs:
                if assigned == question_ref or question_exposure_group(self.connection, self.workspace_id, assigned) == group:
                    raise protected_error()

    def start_exclusion(self, mode: Literal['independent', 'assisted', 'open_book']) -> None:
        if not self.connection.in_transaction:
            raise ApiError(409, 'TRANSACTION_REQUIRED', '测验开始排他检查需要有效事务。')
        if self.assessments.active_independent() is not None:
            raise active_error()
        if mode == 'independent' and active_subject_work(self.connection, self.workspace_id):
            raise ApiError(409, 'SUBJECT_WORK_ACTIVE', '仍有进行中、排队中或待批准的学科任务，请先结束或取消任务。')


def guard_attempt_access(connection: sqlite3.Connection, workspace_id: str, attempt_id: str, *,
                         assessment_ref: dm.ContentRef | None = None) -> AttemptAccess:
    policy = Policy(connection, workspace_id)
    policy.check('attempt_read', attempt_id=attempt_id)
    access = policy.assessments.load(attempt_id)
    if assessment_ref is not None and access.assessment_ref != assessment_ref:
        raise ApiError(409, 'ASSESSMENT_REFERENCE_MISMATCH', '事件必须绑定本次作答冻结的测验修订。')
    return access

def active_independent(self) -> str | None:
    # Even an incomplete legacy allocation continues to lock academic data.
    row = self.connection.execute(
        "SELECT id FROM attempts WHERE workspace_id=? AND mode='independent' AND status='active' ORDER BY id LIMIT 1",
        (self.workspace_id,),
    ).fetchone()
    return str(row['id']) if row else None

def load(self, identifier: str) -> AttemptAccess:
    # Assignment/submission hashes are checked by their owner. Submission
    # event/outbox links intentionally are NOT checked during Policy: these
    # are appended immediately after the state transition in the same TX.
    value = AssessmentRepository(self.connection, self.workspace_id).load(identifier)
    return AttemptAccess(value.id, value.workspace_id, value.assessment_ref, value.status,
                         value.policy, tuple(value.question_refs))

def active_open_book(self) -> str | None:
    row = self.connection.execute(
        "SELECT id FROM attempts WHERE workspace_id=? AND mode='open_book' AND status='active' ORDER BY id LIMIT 1",
        (self.workspace_id,),
    ).fetchone()
    return str(row['id']) if row else None

def protected(self) -> tuple[AttemptAccess, ...]:
    rows = self.connection.execute(
        "SELECT id FROM attempts WHERE workspace_id=? AND (status='active' OR "
        "(mode='independent' AND status IN ('submitted','grading','needs_review'))) ORDER BY id", (self.workspace_id,),
    ).fetchall()
    return tuple(self.load(row['id']) for row in rows)

def connect(self, *, busy_timeout_ms: int = 10_000) -> Iterator[sqlite3.Connection]:
    if type(busy_timeout_ms) is not int or not 0 <= busy_timeout_ms <= 10_000:
        raise ValueError("SQLite busy timeout must be an integer between 0 and 10000 milliseconds.")
    connection = sqlite3.connect(self.path, timeout=busy_timeout_ms / 1000, isolation_level=None)
    connection.row_factory = sqlite3.Row
    try:
        connection.execute("PRAGMA foreign_keys=ON")
        if connection.execute("PRAGMA foreign_keys").fetchone()[0] != 1:
            raise MigrationError("SQLite foreign keys could not be enabled.")
        if connection.execute("PRAGMA journal_mode=WAL").fetchone()[0] != "wal":
            raise MigrationError("SQLite WAL could not be enabled.")
        connection.execute(f"PRAGMA busy_timeout={busy_timeout_ms}")
        yield connection
    finally:
        connection.close()

@contextmanager
def transaction(self, *, busy_timeout_ms: int = 10_000, immediate: bool = True) -> Iterator[sqlite3.Connection]:
    with self.connect(busy_timeout_ms=busy_timeout_ms) as connection:
        connection.execute("BEGIN IMMEDIATE" if immediate else "BEGIN")
        try:
            yield connection
            connection.commit()
        except BaseException:
            connection.rollback()
            raise

